// Trailing 28-day window ending at the close of the last complete week.
// Matches the stock snapshot's as-of date so the two files describe the
// same moment.

const now = $now.setZone('America/New_York');
const dayOfWeek = now.weekday % 7;
const currentWeekStart = now.minus({ days: dayOfWeek }).startOf('day');

const windowEnd = currentWeekStart.minus({ seconds: 1 });
const windowStart = windowEnd.minus({ days: 28 }).startOf('day');

const fmt = "yyyy-MM-dd'T'HH:mm:ssZZ";
const year = windowEnd.toFormat('yyyy');
const month = windowEnd.toFormat('MM-MMMM');
const asOf = windowEnd.toFormat('yyyy-MM-dd');

return [{
  json: {
    start_date: windowStart.toFormat(fmt),
    end_date: windowEnd.toFormat(fmt),
    window_start_label: windowStart.toFormat('yyyy-MM-dd'),
    window_end_label: asOf,
    period_days: Math.round(windowEnd.diff(windowStart, 'days').days),
    stock_path: `business-decisions-data/cigar-stock/${year}/${month}/${asOf}-cigar-stock.csv`,
    file_path: `business-decisions-data/cigar-inventory/${year}/${month}/${asOf}-cigar-inventory.csv`,
    generated_at: now.toFormat(fmt)
  }
}];

// Parse the stock CSV written by Cigar Stock Snapshot. The GitHub node may
// return the content decoded or base64-encoded depending on version, so
// handle both rather than assuming.

const win = $('Build Window').all()[0].json;
const j = items[0].json;

let text = j.content || j.data || j.file_content || '';

if (typeof text !== 'string' || !text) {
  throw new Error('Stock file returned no content. Expected ' + win.stock_path);
}

// Base64 if it has no comma and no newline but looks encoded.
if (!text.includes(',') && !text.includes('\n')) {
  try { text = Buffer.from(text, 'base64').toString('utf8'); } catch (e) {}
} else if (/^[A-Za-z0-9+/=\s]+$/.test(text) && !text.includes('item_id')) {
  try { text = Buffer.from(text, 'base64').toString('utf8'); } catch (e) {}
}

const rows = text.split('\n').filter(l => l.trim().length);
if (rows.length < 2) {
  throw new Error('Stock file has no data rows: ' + win.stock_path);
}

function splitCsv(line) {
  const out = [];
  let cur = '';
  let inQ = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (inQ) {
      if (ch === '"') {
        if (line[i + 1] === '"') { cur += '"'; i++; } else { inQ = false; }
      } else { cur += ch; }
    } else if (ch === '"') { inQ = true; }
    else if (ch === ',') { out.push(cur); cur = ''; }
    else { cur += ch; }
  }
  out.push(cur);
  return out;
}

const header = splitCsv(rows[0]).map(h => h.trim());
const idx = {};
header.forEach((h, i) => { idx[h] = i; });

for (const needed of ['item_id', 'sku', 'name', 'on_hand', 'unit_cost']) {
  if (!(needed in idx)) throw new Error('Stock file missing column: ' + needed);
}

const stock = [];
for (let r = 1; r < rows.length; r++) {
  const c = splitCsv(rows[r]);
  stock.push({
    item_id: String(c[idx.item_id]),
    sku: c[idx.sku],
    name: c[idx.name],
    on_hand: Number(c[idx.on_hand]) || 0,
    unit_cost: Number(c[idx.unit_cost]) || 0
  });
}

return [{ json: { stock_count: stock.length, stock } }];

// Tally cigar units sold per item, join to stock, emit the analyst CSV:
//   sku, name, units_sold, on_hand, unit_cost
// Every carried cigar is a row, including ones that sold nothing.

const win = $('Build Window').all()[0].json;
const stock = $('Parse Stock').all()[0].json.stock;

// Tally first, then let the raw sales go out of scope.
const sold = {};
for (const item of items) {
  const sale = item.json;
  const cart = sale.cart_items || [];
  for (let i = 0; i < cart.length; i++) {
    const c = cart[i];
    if ((c.category_name || '') !== 'Cigars') continue;
    const id = String(c.item_id);
    sold[id] = (sold[id] || 0) + Number(c.quantity || 0);
  }
}

function csvCell(v) {
  const s = String(v === null || v === undefined ? '' : v);
  return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}

const lines = ['sku,name,units_sold,on_hand,unit_cost'];
let zeroSellers = 0;

for (const s of stock) {
  const units = Math.round(sold[s.item_id] || 0);
  if (units === 0) zeroSellers++;
  lines.push([
    csvCell(s.sku),
    csvCell(s.name),
    units,
    s.on_hand,
    s.unit_cost.toFixed(2)
  ].join(','));
}

return [{
  json: {
    file_path: win.file_path,
    window_label: `${win.window_start_label} to ${win.window_end_label}`,
    period_days: win.period_days,
    carried_skus: stock.length,
    zero_sellers: zeroSellers,
    commit_message: `Cigar inventory ${win.window_end_label} (${stock.length} SKUs, ${win.period_days}-day window, ${zeroSellers} with no sales)`,
    file_content: lines.join('\n') + '\n'
  }
}];

const now = $now.setZone('America/New_York');
const stamp = now.toFormat('yyyy-MM-dd HH:mm:ss ZZZZ');

const first = (items && items[0] && items[0].json) ? items[0].json : {};
const raw = first.error;

let message = 'No error message available';
let detail = '';

if (typeof raw === 'string') {
  message = raw;
  detail = raw;
} else if (raw && typeof raw === 'object') {
  message = raw.message || raw.description || raw.reason || message;
  try { detail = JSON.stringify(raw, null, 2).slice(0, 4000); } catch (e) { detail = 'Could not serialize error payload.'; }
} else {
  try { detail = JSON.stringify(first, null, 2).slice(0, 4000); } catch (e) { detail = 'Could not serialize item.'; }
}

let failedNode = 'unknown step';
try { if ($prevNode && $prevNode.name) failedNode = $prevNode.name; } catch (e) {}

let windowLabel = 'unknown';
let stockPath = 'unknown';
try {
  const w = $('Build Window').all();
  if (w.length) {
    windowLabel = `${w[0].json.window_start_label} to ${w[0].json.window_end_label}`;
    stockPath = w[0].json.stock_path;
  }
} catch (e) {}

const body = [
  '**Cigar Sales Tally failed.**',
  '',
  `- Failed step: \`${failedNode}\``,
  `- Time: ${stamp}`,
  `- Window: ${windowLabel}`,
  `- Stock file expected at: \`${stockPath}\``,
  `- Execution ID: ${$execution.id}`,
  '',
  '### Error',
  '```',
  String(message),
  '```',
  '',
  '### Raw payload',
  '```json',
  detail,
  '```',
  '',
  '---',
  'No inventory file was written. If this failed at Fetch Stock File, check that Cigar Stock Snapshot ran first.'
].join('\n');

return [{
  json: {
    issue_title: `Cigar Sales Tally failed at ${failedNode} - ${now.toFormat('yyyy-MM-dd')}`,
    issue_body: body
  }
}];
